style.css:
@-moz-document domain("youtube.com") {
/* Set up the body to allow the background */
  body {
    background: url("https://media.tenor.com/Ug6C3-6CzJwAAAAi/maxwell-cat.gif") center center fixed !important;
    background-size: cover !important;
    z-index: -999 !important;
  }

  /* Make main YouTube content semi-transparent */
  #page-manager, ytd-app {
    background: rgba(0, 0, 0, 0.8) !important;
    z-index: 1 !important;
  }

  /* Remove white background from certain panels */
  ytd-masthead, #container.ytd-masthead, ytd-mini-guide-renderer {
    background-color: transparent !important;
  }

  /* Optional: hide YouTube Shorts button */
  a[title="Shorts"] {
    display: none !important;
  }
}
